export const statuses=['Pendente','Em andamento','Concluída','Cancelada'];
const catalog=[['001','Papel A4 branco 75g/m²','Resma'],['002','Caneta esferográfica azul','Caixa'],['003','Toner para impressora HP 85A','Unidade'],['004','Pasta suspensa kraft','Unidade'],['005','Copo descartável 200 ml','Pacote'],['006','Álcool em gel 70%','Frasco'],['007','Grampeador de mesa','Unidade'],['008','Envelope ofício branco','Caixa'],['009','Marcador de texto amarelo','Caixa'],['010','Bloco de notas adesivas','Pacote'],['011','Papel toalha interfolhado','Pacote'],['012','Clips galvanizado nº 2','Caixa']].map(([code,product,unit],i)=>({id:'p'+i,code: 'MAT-'+code,product,unit}));
const sectors=[['Administrativo','Ana Paula Ribeiro','administrativo@fazenda.gov.br'],['Contabilidade','Carlos Eduardo Lima','contabilidade@fazenda.gov.br'],['Tributação','Mariana Santos','tributacao@fazenda.gov.br'],['Tesouraria','Rafael Oliveira','tesouraria@fazenda.gov.br'],['Fiscalização','Juliana Costa','fiscalizacao@fazenda.gov.br']].map(([name,responsible,contact],i)=>({id:'s'+i,name,responsible,contact}));
const requests=Array.from({length:24},(_,i)=>({...catalog[i%catalog.length],id:'r'+i,sector:sectors[i%5].name,quantity:[50,12,8,100,30,20,5,10][i%8],status: i<8?'Pendente':i<14?'Em andamento':i<23?'Concluída':'Cancelada',date:`2026-${String(6+Math.floor(i/5)).padStart(2,'0')}-${String(10+i%17).padStart(2,'0')}`,ata:'ATA 012/2026'}));
const initial={products:catalog,sectors,requests,atas:[{id:'a1',number:'ATA 012/2026',supplier:'Papelaria Central Ltda.',validity:'2027-06-30',description:'Materiais de expediente e escritório'},{id:'a2',number:'ATA 018/2026',supplier:'Higiene & Cia Suprimentos',validity:'2027-08-15',description:'Materiais de limpeza e higiene'}],demo:true,columns:['code','product','unit','quantity','sector','status'],theme:'light'};
let data;try{data=JSON.parse(localStorage.getItem('supri-v1'))||structuredClone(initial)}catch{data=structuredClone(initial)}
export const Store={data,save(){try{localStorage.setItem('supri-v1',JSON.stringify(this.data));document.getElementById('save-state').innerHTML='<i></i> Todas as alterações salvas';return true}catch{document.getElementById('save-state').textContent='Falha ao salvar: exporte um backup';return false}},add(type,record){this.data[type].unshift({...record,id:crypto.randomUUID()});this.save();return this.data[type][0]},update(type,id,record){const i=this.data[type].findIndex(x=>x.id===id);if(i>=0)this.data[type][i]={...this.data[type][i],...record};this.save()},remove(type,ids){this.data[type]=this.data[type].filter(x=>!ids.includes(x.id));if(type==='products'||type==='sectors'){const key=type==='products'?'productIds':'sectorIds';for(const ata of this.data.atas)ata[key]=(ata[key]||[]).filter(id=>!ids.includes(id))}this.save()}};
